const prenom = document.querySelector("#prenom");
const ville = document.querySelector("#ville");
const profil = document.querySelector("#profil");
function rendre() {
  let nomAffiche = prenom.value;
  let villeAffichee = ville.value;
  if (nomAffiche === "") { nomAffiche = "Prénom ?"; }
  if (villeAffichee === "") { villeAffichee = "Ville ?"; }
  profil.textContent = nomAffiche + " · " + villeAffichee;
}
prenom.addEventListener("input", rendre);
ville.addEventListener("input", rendre);
rendre();

