const nom = document.querySelector('#nom');
const places = document.querySelector('#places');
const liste = document.querySelector('#liste');
const retour = document.querySelector('#retour');
function signaler(champ, message) {
  document.querySelector('#erreur-' + champ.id).textContent = message;
  champ.setAttribute('aria-describedby', 'aide-' + champ.id + (message ? ' erreur-' + champ.id : ''));
  if (message) champ.setAttribute('aria-invalid', 'true');
  else champ.removeAttribute('aria-invalid');
}
document.querySelector('#formulaire').addEventListener('submit', event => {
  event.preventDefault();
  const texte = nom.value.trim();
  const quantite = Number(places.value);
  const mauvaisNom = texte.length < 2 || texte.length > 20;
  const mauvaisesPlaces = places.value.trim() === '' || !Number.isInteger(quantite) || quantite < 1 || quantite > 8;
  signaler(nom, mauvaisNom ? 'Écris un nom de 2 à 20 caractères.' : '');
  signaler(places, mauvaisesPlaces ? 'Choisis un entier de 1 à 8.' : '');
  if (mauvaisNom) {
    retour.textContent = '';
    (mauvaisNom ? nom : places).focus();
    return;
  }
  const li = document.createElement('li');
  li.textContent = texte + ' : ' + quantite;
  liste.append(li);
  retour.textContent = 'Ajout fictif effectué.';
});

